cat > merge.py <<'EOF'
import json, pandas as pd

MAP = {"user_id":"user_id","id":"user_id","userId":"user_id",
       "email":"email","email_address":"email",
       "full_name":"name","name":"name","userName":"name",
       "registration_date":"created_date","created_at":"created_date","joined":"created_date",
       "status":"status"}
FIELDS = ["name","email","created_date","status"]

def norm_date(v):
    if v is None or (isinstance(v,float) and pd.isna(v)): return None
    try: return pd.to_datetime(v).strftime("%Y-%m-%d")
    except Exception: return str(v)

def to_status(v):
    if v is None or (isinstance(v,float) and pd.isna(v)): return None
    if isinstance(v,str):
        s=v.strip().lower()
        if s in ("true","1","yes"): return "active"
        if s in ("false","0","no"): return "inactive"
        return v
    return "active" if bool(v) else "inactive"

def load(df):
    df = df.copy()
    for b in ("is_active","active"):
        if b in df.columns and "status" not in df.columns:
            df["status"] = df[b].map(to_status)
    df = df.rename(columns={c:MAP[c] for c in df.columns if c in MAP})
    recs = {}
    for r in df.to_dict("records"):
        if r.get("user_id") is None or pd.isna(r["user_id"]): continue
        uid = int(r["user_id"])
        rec = {}
        for f in FIELDS:
            v = r.get(f)
            if v is not None and not (isinstance(v,float) and pd.isna(v)):
                rec[f] = norm_date(v) if f=="created_date" else str(v).strip()
        recs[uid] = rec
    return recs

srcs = {
 "source_a": load(pd.DataFrame(json.load(open("/data/source_a/users.json")))),
 "source_b": load(pd.read_csv("/data/source_b/users.csv", dtype=str)),
 "source_c": load(pd.read_parquet("/data/source_c/users.parquet")),
}
order = ["source_a","source_b","source_c"]
ids = sorted(set().union(*[s.keys() for s in srcs.values()]))
rows, conflicts = [], []
for uid in ids:
    row = {"user_id": uid}
    for f in FIELDS:
        vals = {s: srcs[s][uid][f] for s in order if uid in srcs[s] and f in srcs[s][uid]}
        sel = next(iter(vals.values()), None)
        row[f] = sel
        if len(set(vals.values())) > 1:
            conflicts.append({"user_id": uid, "field": f, "values": vals, "selected": sel})
    rows.append(row)

out = pd.DataFrame(rows, columns=["user_id","name","email","created_date","status"])
out["user_id"] = out["user_id"].astype("int64")
for c in ["name","email","created_date","status"]: out[c] = out[c].astype("string")
out.to_parquet("/app/merged_users.parquet", index=False)
json.dump({"total_conflicts": len(conflicts), "conflicts": conflicts}, open("/app/conflicts.json","w"), indent=2)
print(out.to_string()); print(out.dtypes)
EOF
./envrun 'cat > /app/merge.py' < merge.py && ./envrun 'python3 /app/merge.py && cat /app/conflicts.json && python3 -c "import pyarrow.parquet as pq; print(pq.read_schema(\"/app/merged_users.parquet\"))"'
